// ===== 91PORN 线路注入（261107 新增）=====
// BaseSource.evalJS 每次把 jsLib 注入脚本作用域，source 绑定可用；
// PN_base() 在 sortUrl / searchUrl 的 {{}} 内联 JS 里「请求时」求值，
// 因此登录面板切了 pnLine 后，下一次拉列表/搜索立即落在新线路，
// 不受 sortUrls() 的 ACache 缓存影响（@js: 整段脚本方案会被缓存坑住）。
// ===== 261108 三轮修复：线路变量走 this.source.getVariable() =====
// 诊断实锤：{{}} 的 jsLib 共享 scope 里裸 source/cache/java/baseUrl 全部不可用，
// 但 this.source.getVariable() 可用（与既有 getData() 同通道）。
function PN_var() {
  var o = {};
  try {
    var v = '';
    try { v = String(this.source.getVariable() || ''); } catch (e0) { v = ''; }
    if (v) o = JSON.parse(v) || {};
  } catch (e) { o = {}; }
  return o;
}
// 写线路到 variable（保留起始页码 page，绝不写死页码上限）
function PN_setVarLine(line) {
  var o = PN_var.call(this);
  if (!o.page) o.page = '1';
  o.pnLine = String(line || '');
  try { this.source.setVariable(JSON.stringify(o)); } catch (e) {}
  return o;
}
function PN_base() {
  var ok = function (v) {
    var s = '';
    try { s = String(v); } catch (e) { return ''; }
    return (s && s !== 'null' && s !== 'undefined' && s.indexOf('http') === 0) ? s : '';
  };
  var d = '';
  // ① 主通道：variable.pnLine（this.source 在 {{}} 共享 scope 可用，诊断版4 实锤）
  try { d = ok(PN_var.call(this).pnLine); } catch (e) { d = ''; }
  // ② 面板原生 source.put 通道（部分版本可用）
  if (!d) { try { d = ok(source.get('pnLine')); } catch (e2) { d = ''; } }
  // ③ CacheManager 精确键（需要 cache 绑定；缺失则跳过）
  if (!d) {
    try {
      var key = '';
      try { key = String(this.source.key || ''); } catch (e3) { key = ''; }
      if (!key) { try { key = String(source.sourceUrl || ''); } catch (e4) {} }
      if (!key) key = 'https://418.sol148.com/index.php';
      d = ok(cache.get('v_' + key + '_pnLine'));
    } catch (e5) { d = ''; }
  }
  // ④ java.get 兜底
  if (!d) { try { d = ok(java.get('pnLine')); } catch (e6) { d = ''; } }
  if (!d) d = 'https://a.26702.app';
  return d.replace(/\/+$/, '');
}

