// ==================== 91PORN(订阅) · 发布页/线路管理面板 ====================
// 用途（全部函数挂在 loginUrl，SourceLoginDialog 把 "$loginJS\n$action" 一起 eval）：
//   ① 发布页输入框：用户可改发布页地址（默认 91p676.com，meta refresh 到 a.26702.app/1.php）
//   ② 🧭 一键从发布页获取网址路线：抓 meta refresh / 302 Location，解析出线路域名池
//   ③ ⏱ 检测路线延迟(ms)：java.connect 逐线路请求 /index.php，callTime() 取 ms，
//      写入 pnDelay0..N，由 PN_lineBtn 动态 viewName 显示在各路线按钮上
//   ④ 各路线按钮：点按切换 pnLine；sortUrl/searchUrl 的 {{PN_base()}} 在请求时
//      读取 pnLine（绕过 @js: sortUrl 的 ACache 缓存），切换后即时生效
//   ⑤ 🔍 检查登录状态/线路可用性 + 🌐 打开网站(登录)（保留原功能）
// 兼容 LegadoTeam(LT) + legado-E：V1 静态 loginUi；text 输入值由 getLoginData()
// 注入为 result Map（键=行 name），按钮 action 用 PN_pubFrom(result) 读取；
// viewName 动态表达式在 evalUiJs 环境无 java 绑定，故只读 source/cache，不调用 java。
var PN_MAX = 6;
var PN_PUB_DEFAULT = 'http://91p676.com';
var PN_LINE_DEFAULT = 'https://a.26702.app';
var PN_UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';
// 内置兜底线路（均来自源注释/发布页实测，不含写死页码上限）：
// 发布页 host 本身即完整站点；其余为历史镜像，供测速对比。
var PN_FALLBACK = [
  'https://a.26702.app',
  'https://418.sol148.com',
  'https://a1019.9p58b.com',
  'https://f1011.a2507app.com',
  'https://902.9p234.com'
];

function PN_toast(t) {
  try { java.longToast(String(t)); } catch (e) { try { java.toast(String(t)); } catch (e2) {} }
}
function PN_gv(k, def) {
  var v = '';
  try { v = String(source.get(k)); } catch (e) { v = ''; }
  if (v === '' || v === 'null' || v === 'undefined') v = def || '';
  return v;
}
function PN_norm(u) {
  var s = String(u || '').trim().replace(/\/+$/, '');
  if (s === '') return '';
  if (s.indexOf('http') !== 0) s = 'https://' + s;
  // 只保留 scheme://host[:port]，丢掉路径（发布页/线路域名都按根站使用）
  var m = /^(https?:\/\/[^/]+)/.exec(s);
  if (m) s = m[1];
  return s;
}
function PN_host(u) {
  var m = /^https?:\/\/([^/]+)/.exec(String(u));
  return m ? m[1] : String(u);
}
function PN_hdr() { return JSON.stringify({ 'User-Agent': PN_UA, 'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8' }); }

// ---------- 发布页输入框 ----------
function PN_pub() {
  var p = PN_gv('pnPub', PN_PUB_DEFAULT);
  p = PN_norm(p);
  return p === '' ? PN_PUB_DEFAULT : p;
}
// action 环境 result = getLoginData(rowUis)（Java MutableMap<行name, 输入框文本>）
function PN_pubFrom(r) {
  var v = '';
  try { if (r && r.get) v = String(r.get('发布页') || ''); } catch (e0) { v = ''; }
  if (!v) { try { v = String(r['发布页'] || ''); } catch (eA) { v = ''; } }
  if (!v) { try { if (result && result.get) v = String(result.get('发布页') || ''); } catch (e1) {} }
  if (!v) { try { if (result) v = String(result['发布页'] || ''); } catch (eB) {} }
  if (!v || !v.trim()) v = PN_PUB_DEFAULT;
  var p = PN_norm(v);
  source.put('pnPub', p);
  PN_toast('✅ 发布页已设为：' + PN_host(p) + '（点「🧭 一键从发布页获取网址路线」生效）');
  PN_refresh();
}
function PN_pubHint() {
  return "'发布页(默认91p676.com)'";
}

// ---------- 线路池持久化 ----------
function PN_setFound(list) {
  var out = [], i, u;
  for (i = 0; i < list.length && out.length < PN_MAX; i++) {
    u = PN_norm(list[i]);
    if (u && out.indexOf(u) < 0) out.push(u);
  }
  if (!out.length) out = PN_FALLBACK.slice(0);
  source.put('pnFound', out.join(' '));
  for (i = 0; i < PN_MAX; i++) source.put('pnDelay' + i, '');
  return out;
}
function PN_found() {
  var s = PN_gv('pnFound', '');
  if (!s) return PN_setFound(PN_FALLBACK);
  var a = s.split(/\s+/), out = [], i;
  for (i = 0; i < a.length && out.length < PN_MAX; i++) {
    var u = PN_norm(a[i]);
    if (u.indexOf('http') === 0 && out.indexOf(u) < 0) out.push(u);
  }
  return out.length ? out : PN_setFound(PN_FALLBACK);
}
// 统一写线路：source.put + variable 双写（PN_base 走 getVariable 读取）
function PN_writeLine(line) {
  var L = String(line || '');
  try { source.put('pnLine', L); } catch (e0) {}
  try { source.put('pnLineHost', L.replace(/^https?:\/\//, '').replace(/\/.*$/, '')); } catch (e1) {}
  try {
    if (typeof PN_setVarLine === 'function') PN_setVarLine.call(source, L);
    else {
      var o = {}, v = '';
      try { v = String(source.getVariable() || ''); } catch (e2) { v = ''; }
      try { o = v ? (JSON.parse(v) || {}) : {}; } catch (e3) { o = {}; }
      if (!o.page) o.page = '1';
      o.pnLine = L;
      source.setVariable(JSON.stringify(o));
    }
  } catch (e4) {}
  return L;
}
function PN_line() {
  var d = PN_norm(PN_gv('pnLine', PN_LINE_DEFAULT));
  return d.indexOf('http') === 0 ? d : PN_LINE_DEFAULT;
}
function PN_absUrl(u, base) {
  var s = String(u || '').trim();
  if (!s) return '';
  if (s.indexOf('http') === 0) return PN_norm(s);
  if (s.indexOf('//') === 0) return PN_norm('https:' + s);
  var b = PN_norm(base).replace(/\/+$/, '');
  if (s.charAt(0) !== '/') s = '/' + s;
  return PN_norm(b + s);
}

// ---------- 🧭 一键从发布页获取网址路线 ----------
// 发布页 91p676.com：200 + <META HTTP-EQUIV=Refresh CONTENT="0; URL=https://a.26702.app/1.php">
// 二级 a.26702.app/1.php：302 Location: https://902.9p234.com（当前官方线路）
// 解析策略：抓 meta refresh → GET 目标 → 若 302 取 Location；同时把发布页 host
// 本身（完整站点）加入池，历史上已记录的同源镜像一并纳入，按去重建最多 PN_MAX 条。
//  meta refresh / 302 Location 解析（★不削路径：/1.php 才是发布页跳转入口，
//  削成根域会命中 18+ 入口页 200 而拿不到 Location）
function PN_fetchPub() {
  var pub = PN_pub();
  PN_toast('🧭 开始获取：正在打开发布页 ' + PN_host(pub));
  var raw = '', err = '';
  try {
    var r0 = java.connect(pub + '/', PN_hdr(), 15000);
    raw = String(r0.body());
    if (r0.code && r0.code() !== 200) err = 'HTTP ' + r0.code();
  } catch (e) { err = String(e).substring(0, 90); }
  if (err === '' && (raw.length < 20 || raw.indexOf('Exception') === 0)) err = '发布页内容异常';
  if (err !== '') {
    PN_toast('⚠ 发布页抓取失败(' + err + ')，载入内置 ' + PN_FALLBACK.length + ' 条兜底线路');
    PN_setFound(PN_FALLBACK);
    PN_toast('✅ 已载入内置线路，请点「⏱ 检测路线延迟」');
    PN_refresh(); return;
  }
  PN_toast('🔓 发布页已获取(' + raw.length + 'B)，正在解析跳转…');
  var lines = [], i, u;
  // ① meta refresh 目标（保留 /1.php 路径，交给 java.head 取 302 Location）
  var meta = /URL\s*=\s*['"]?([^'"\s>]+)/i.exec(raw);
  var next = '';
  if (meta) next = PN_absUrl(meta[1], pub);
  if (next) {
    PN_toast('↪ 发布页跳转 → ' + PN_host(next));
    // 「发布页 host」本身是完整站点（a.26702.app/index.php 实测可访问），先入池
    var nh = PN_norm(next);
    if (nh && lines.indexOf(nh) < 0) lines.push(nh);
    var loc = '';
    try {
      var h = java.head(next, PN_hdr(), 12000);
      var sc = Number(h.statusCode ? h.statusCode() : 0);
      if (sc === 301 || sc === 302 || sc === 307 || sc === 308) {
        try { loc = String(h.header('Location') || ''); } catch (eL) { loc = ''; }
      }
    } catch (e2) { loc = ''; }
    if (loc) {
      u = PN_absUrl(loc, next);
      if (u && lines.indexOf(u) < 0) lines.push(u);
    }
  }
  // ② 发布页正文里出现的同族镜像域名（排除 CDN/图床/统计信标）
  var re = /https?:\/\/([a-z0-9][a-z0-9.\-]*\.[a-z]{2,})/gi, m, hn;
  var BAD = /(cloudflare|cloudfront|google|gstatic|alicdn|cdn77|w3\.org|beacon|insights|liongege|91selfie|ganyiwanghe|china-goon|gcfang|sjhf120|zhongpinwenhua|hpv112|googletagmanager)/i;
  while ((m = re.exec(raw)) !== null) {
    u = PN_norm(m[0]); hn = PN_host(u);
    if (BAD.test(hn)) continue;
    if (/^[a-z0-9]+\.[a-z0-9]+\.(com|net|app|cc|xyz|rest)$/i.test(hn) ||
        hn.indexOf('9p') > -1 || hn.indexOf('sol') > -1 ||
        hn.indexOf('a2507') > -1 || hn.indexOf('26702') > -1) {
      if (lines.indexOf(u) < 0) lines.push(u);
    }
  }
  // ③ 内置兜底补齐（保证按钮始终有可切换对象；站点以后加数据也自动跟随）
  for (i = 0; i < PN_FALLBACK.length && lines.length < PN_MAX; i++) {
    if (lines.indexOf(PN_FALLBACK[i]) < 0) lines.push(PN_FALLBACK[i]);
  }
  var got = PN_setFound(lines);
  // 取路线后同步一次 variable（避免 pnLine 只存在于 put 通道而 PN_base 读不到）
  try { PN_writeLine(PN_line()); } catch (eW) {}
  PN_toast('✅ 共获取 ' + got.length + ' 条路线：' + got.map(PN_host).join(' / '));
  PN_toast('已写入各路线按钮；请点「⏱ 检测路线延迟」把 ms 写进按钮名');
  PN_refresh();
}

// ---------- ⏱ 检测路线延迟（ms 写入各路线按钮） ----------
// 判活三判据：code 200-399 + body 非异常堆栈 + body 含站点特征。
// 注意 java.ajax/connect 失败时返回异常堆栈串而非抛异常（源码 runCatching 包 body），
// 因此必须显式排除 'Exception'/'timeout' 且长度过短的堆栈串。
function PN_testAll() {
  var list = PN_found();
  PN_toast('⏱ 开始测速：共 ' + list.length + ' 条线路，逐个请求 /index.php（约 ' + (list.length * 3) + ' 秒）…');
  var i, r, b, ms, tag, best = -1, bestMs = 999999;
  for (i = 0; i < list.length; i++) {
    ms = -1; tag = '✗ 不可达';
    try {
      r = java.connect(list[i] + '/index.php', PN_hdr(), 10000);
      b = String(r.body());
      if (b.indexOf('Exception') > -1 || b.indexOf('timeout') > -1) {
        // java.connect 失败时不抛异常，而是 code=200 + 异常堆栈串当 body
        // （JsExtensionsAndroid runCatching 包 body）⇒ 明确标成「不可达」而非 HTTP/200
        tag = '✗ 不可达';
      } else if (r.code && (r.code() < 200 || r.code() >= 400)) {
        tag = '✗ HTTP/' + r.code();
      } else if (b.length < 500) {
        tag = '✗ 内容异常';
      } else {
        // callTime() 是 StrResponse 真机计时（毫秒）；缺失时退化为本地计时
        ms = r.callTime ? Number(r.callTime()) : -1;
        if (ms < 0 || isNaN(ms)) ms = 0;
        tag = ms + 'ms';
        if (ms < bestMs) { bestMs = ms; best = i; }
      }
    } catch (e) { tag = '✗ ' + String(e).substring(0, 36); }
    source.put('pnDelay' + i, tag);
    PN_toast('  [' + (i + 1) + '/' + list.length + '] ' + PN_host(list[i]) + ' → ' + tag);
  }
  if (best >= 0) {
    source.put('pnDelay' + best, '⚡' + bestMs + 'ms');
    PN_toast('🏁 测速完成：最快 ' + PN_host(list[best]) + ' ' + bestMs + 'ms（点对应路线按钮切换）');
  } else {
    PN_toast('⚠ 测速完成：暂无可用线路，可点「🧭 一键从发布页获取网址路线」刷新后重试');
  }
  PN_refresh();
}

// ---------- 🔍 检查登录状态 / 线路可用性 ----------
function PN_checkLogin() {
  var d = PN_line();
  PN_toast('🔍 正在检查当前线路：' + PN_host(d));
  var b = '', code = 0;
  try {
    var r = java.connect(d + '/index.php', PN_hdr(), 15000);
    b = String(r.body());
    try { code = r.code ? r.code() : 0; } catch (eC) { code = 0; }
  } catch (e) { PN_toast('❌ 检查失败：' + String(e).substring(0, 90)); return; }
  if (b.indexOf('Exception') > -1 || (code && (code < 200 || code >= 400)) || b.length < 5000) {
    PN_toast('❌ 当前线路不可用(' + (b.indexOf('Exception') > -1 ? '连接异常' : 'HTTP ' + code + ', ' + b.length + 'B') + ')，建议测速后切换线路'); return;
  }
  var needLogin = /(请先登录|登录后查看|需要登录|会员专享|VIP专属)/.test(b);
  var hasUser = /(logout|退出登录|signout)/i.test(b);
  PN_toast('✅ 线路正常(' + b.length + 'B)；' + (needLogin ? '⚠ 检测到登录墙' : '列表页可访问') + (hasUser ? '；已检测到登录态' : '；当前为游客态') + '；点「🌐 打开网站」可登录');
}

// ---------- 各路线按钮：动态文字 + 切换 ----------
// 当前线路动态文本（loginUi 里 label 的 viewName 每次渲染重跑；必须返回纯文本）
function PN_curLineText() {
  var l = PN_line();
  var dl = '';
  try { dl = String(PN_gv('pnDelay' + PN_found().indexOf(l), '')); } catch (e) {}
  return '📍 当前线路：' + PN_host(l) + (dl ? '（' + dl + '）' : '') + '｜点下方按钮切换';
}
function PN_lineBtn(n) {
  var list = PN_found(), i = Number(n) - 1;
  if (i < 0 || i >= list.length) return '━━ 路线' + n + ' 未获取 ━━';
  var cur = PN_line(), mark = (list[i] === cur) ? '▶ ' : '　 ';
  var dl = PN_gv('pnDelay' + i, '');
  if (dl) mark += dl + ' ';
  // ★动态 viewName 求值结果被直接设成按钮文字（E 版 evalUiJs 仅 .toString()，
  //   LT 版 normalizeJsResult 也不剥引号）⇒ 必须返回纯文本，绝不能自带外层单引号。
  return mark + PN_host(list[i]);
}
function PN_switch(n) {
  var list = PN_found(), i = Number(n) - 1;
  if (i < 0 || i >= list.length) { PN_toast('⚠ 路线 ' + n + ' 尚未获取，请先点「🧭 一键从发布页获取网址路线」'); return; }
  var old = PN_line(), nw = list[i];
  PN_writeLine(nw);
  // {{PN_base()}} 在每次请求时读 pnLine，切换后下一次拉列表/搜索即时落在新线路；
  // ruleLink 的 @js 同源重写也读同一个 PN_base() ⇒ 文章链接不再钉死旧域。
  // pnSortRev 仅作为运维标记（供排查「是否已切换」），不再是缓存失效的手段。
  PN_bumpRev();
  PN_toast('🔄 已切换：' + PN_host(old) + ' → ' + PN_host(nw));
  PN_toast('✅ 列表/搜索/文章链接/正文全部跟随新线路；请回到订阅页下拉刷新');
  PN_toast('📍 当前线路：' + PN_host(PN_line()));
  PN_refresh();
}
function PN_bumpRev() {
  var v = 0;
  try { v = parseInt(PN_gv('pnSortRev', '0'), 10) || 0; } catch (e) { v = 0; }
  source.put('pnSortRev', String(v + 1));
}
function PN_refresh() {
  var ok = false;
  try { java.reLoginView(); ok = true; } catch (e) {
    try { java.reLoginView(false); ok = true; } catch (e2) { ok = false; }
  }
  if (!ok) PN_toast('ℹ 按钮文字可能未即时刷新：重新打开本面板即可看到「📍 当前线路」与 ▶ 标记');
}

// ---------- 保留原功能：起始页码 / 打开网站 / 更新书源 ----------
// 原 jsLib 的 getData/getPage/getUrl2 用 this.source，登录面板的 loginUrl 环境里
// 这些函数仍挂在 source.evalJS 的共享作用域，但为稳妥这里不依赖 jsLib。
function PN_getPage() {
  var v = '{}';
  try { v = String(source.getVariable() || '{}'); } catch (e) { v = '{}'; }
  var data = {};
  try { data = JSON.parse(v) || {}; } catch (e2) { data = {}; }
  var p = (data.page === '' || data.page == undefined) ? '' : parseInt(data.page, 10) - 1;
  return isNaN(p) ? '' : p;
